params.script_inline:
"""The turn door of a simple-agent hive: the one cell that speaks the hive's rim (contract V-T).

stdin is {envelope, body, params}; stdout a JSON array of content documents (multi-send). A cell writes no
context: every key a later message needs rides on the hop, and the edge that carries it lifts it into the
context. RAM holds only what a new child can do without (`resident`): whether the menu tick ran, which rounds
already armed their watchdog, which turns were answered, which proposals wait for the colony's answer.

The agent keeps no record of people and no key (simple-agent 2, R-SA-37): its identity arrives by pack from the
colony's affinity, and the affinity tool's writes leave on the rim to the agent's entry there.

Turns queue (F29): the door takes the turns of several callers and runs ONE at a time to its end (one round, one
window); the next is the queued one of the highest `priority` (0 first, default 5), then the earliest. A turn that has
not begun by its `deadline_ms` (epoch ms) ends as `answer {expired: true}` without a model call -- also behind a
turn that hangs: one one-shot watchdog (`deadline`), re-armed to the earliest deadline of the queue, wakes the door
for it (R-AG-1, no tick). The door's durable
state -- the queue, the open turn, the answered turn ids (seven days), the start-memory mark, the open client calls --
lives in `./door_store` (a code cell has no `cell.db`): every child life reads it back before its first message, so a
restart loses no queued turn and answers no turn id twice. A read `./door_store` does not answer within
`store_read_ms` is asked again (a one-shot watchdog `ds-read`), so a lost answer never holds the door shut.

The rim:
  in   turn {messages, tools[]?, tool_scope{require?}?}
                                            hop turn_id, session_id, channel, audience_set, counterpart?, caller?,
                                                priority?, deadline_ms?, required_tools?, stage? (fast|strong)
       tool_result {id, content, is_error?}  hop turn_id, session_id, iter, channel, audience_set (as `calls` had)
       close {session_id}
       in_propose_ack                       the colony affinity's ack (or error) of one `affinity_propose`
  out  answer {turn_id, text, iters, usage {in, cached_in, cache_write, out}, cost, stage, partial?, stale?,
               expired?, missing_required?} | error {error_code, ...}     hop turn_id, caller (as the turn had it)
       calls {id, name, arguments}           hop turn_id, session_id, iter, channel, audience_set, tool_name,
                                              tool_call_id -- one message per client call
       close_report {session_id, ok, added, closed}
       affinity_propose                     one write of the affinity tool, as affinity's `in_propose` takes it:
                                              hop agent_id + the round keys
"""
import datetime
import json
import sys
import time

# The frame of every agent this template grows (R-GD-2): an AI, truthful about being one, that works through
# its tools and stops when it is done. Nothing about a world, a day or a last move (R-SA-9).
FRAME = ("You are an AI agent. You work on what you are asked by thinking and by calling the tools you are "
         "given; when a tool answers, you read its result and decide the next step, and when the work is "
         "done you answer in plain text and stop. You never claim to be human: if someone asks you directly "
         "whether you are an AI, you say truthfully that you are. You may decline anything you would not do, "
         "in your own words.")
# The agent's write port into its entry in the colony's affinity (OR-SA-16): the record extends itself only
# through this tool -- the memory proposes nothing to it in the core.
AFFINITY_OPS = ("add_relation", "retract_relation", "set_trust", "propose", "upsert_entity")
AFFINITY_TOOL = {
    "name": "affinity_propose",
    "description": ("Write to your own record of people and agents: a relation between two entities "
                    "(add_relation {src, dst, kind, weight}), its retraction (retract_relation {id}), how far "
                    "you trust someone (set_trust {entity_id, audience, level}), a proposed fact about a person "
                    "(propose {source_ref, entity_ref, field_path, value}), or a whole AIeOS document "
                    "(upsert_entity {entity_id, kind, display_name, aieos})."),
    "parameters": {"type": "object", "properties": {
        "op": {"type": "string", "enum": list(AFFINITY_OPS)}},
        "required": ["op"], "additionalProperties": True}}
ROUND_PREFIX = "history_"
SEED_SESSION = "seed"
DEFAULT_PRIORITY = 5
# How long an answered turn id is refused as seen (plan A2, "beantwortete turn_ids (7 Tage)").
SEEN_KEEP_MS = 7 * 24 * 3600 * 1000
STATE_TABLE = "state"
STATE_SLOT = "door"
# What a child life must find again after a restart; everything else is RAM (`resident`).
DURABLE = ("queue", "active", "turns", "answered", "seeded", "pending", "calls", "timed_out", "seq", "sessions",
           "enabled", "deadline_at")
# The agent's own tools that are always on (plan A4): the memory's recall and the round tools.
CORE_TOOLS = ("memory_recall",)


# >>> watchdog v1 (R-AG-1, GH #1096)
import datetime as _wd_dt
import uuid as _wd_uuid

WATCHDOG_NS = _wd_uuid.UUID("6f1c2a8e-3b7d-5e90-9a41-0c2d7e5b8f13")


def watchdog_id(name):
    """Stable schedule id for a watchdog name: re-arming the name replaces it."""
    return str(_wd_uuid.uuid5(WATCHDOG_NS, str(name)))


def _iso(ms):
    return _wd_dt.datetime.fromtimestamp(
        int(ms) / 1000.0, tz=_wd_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")


def once(name, at_ms, emit_to, body, catch_up=True):
    """One-shot watchdog: fires once at `at_ms` (epoch ms). `at_ms` must lie
    ahead: the timer refuses a past moment (`at_in_past`), so a caller whose
    moment has come does the work now instead of arming. `catch_up` (default
    on) fires a moment missed while the colony was down once on its next
    start, with `late: true`; without it a missed watchdog never fires."""
    return {"op": "add", "schedule_id": watchdog_id(name), "schedule_name": str(name),
            "at": _iso(at_ms), "emit_to": emit_to, "emit_body": body,
            "rearm": True, "catch_up": bool(catch_up)}


def retrigger(name, now_ms, quiet_ms, emit_to, body):
    """Debounce: fires `quiet_ms` (> 0) after the last call; every call
    pushes it out."""
    return once(name, int(now_ms) + max(1, int(quiet_ms)), emit_to, body)


def calendar(name, cron, emit_to, body):
    """Calendar watchdog (Jenkins-style): real calendar points only, never a
    tick. `cron` is the timer's 6-field Quartz form, seconds first, in UTC
    (`0 0 3 * * *`)."""
    return {"op": "add", "schedule_id": watchdog_id(name), "schedule_name": str(name),
            "cron": cron, "emit_to": emit_to, "emit_body": body, "rearm": True}


def cancel(name):
    """Disarm a watchdog by name. A watchdog that is not armed (never armed,
    already fired) answers `timer_op_error` / `schedule_not_found`."""
    return {"op": "remove", "schedule_id": watchdog_id(name)}
# <<< watchdog v1


def _obj(v):
    return v if isinstance(v, dict) else {}


def _text(t):
    return t if isinstance(t, str) else json.dumps(t, ensure_ascii=False)


def _turn(text):
    return [{"origin": "assistant", "type": "text", "text": text}]


def rim(route, slot, hop=None):
    """One message on a lane of the hive's rim: the body slot of the lane's name and one plain turn.
    `sa_rim` tells the hive's door edges that this message leaves, so the edge of the same lane never takes it
    back in."""
    head = {"route": route, "sa_rim": "out"}
    head.update(hop or {})
    return {"header": head, route: slot, "messages": _turn(route)}


def agent_id(params):
    return str(params.get("agent_id") or "agent")


def now_ms(params):
    """Epoch milliseconds: `params.now_utc` (an ISO instant) when a test sets it, the wall clock otherwise."""
    fixed = str(params.get("now_utc") or "")
    if fixed:
        try:
            return int(datetime.datetime.fromisoformat(fixed.replace("Z", "+00:00")).timestamp() * 1000)
        except ValueError:
            pass
    # wall-clock: now_utc
    return int(time.time() * 1000)


def round_keys(src):
    """The five keys that name a round, read from a hop or a context (contract V-T)."""
    return {k: str(src.get(k)) for k in ("turn_id", "session_id", "iter", "channel", "audience_set")
            if src.get(k) is not None}


def own_names(params, st):
    """The own tool names that stand in the menu: the core tools always, a family's tools only while the
    family is enabled (`tools_enabled` of the agent, told to the door on the `tools_enabled` lane; A4,
    OR-AG-7). A client tool of a name whose family is off passes -- the caller's tools always do."""
    enabled = {str(n) for n in (st.get("enabled") or []) if isinstance(n, str)}
    names = [str(n) for n in (params.get("own_tools") or []) if isinstance(n, str)]
    on = {n for n in names if n in CORE_TOOLS or n.startswith(ROUND_PREFIX) or n in enabled
          or n.split("_", 1)[0] in enabled}
    return on | {AFFINITY_TOOL["name"]}


def is_own(params, name, st):
    """An own tool's name, the family word its tools fold into (`web` of `web_fetch`/`web_search`), or a
    round tool -- a client tool of that name would be shadowed in the menu, so it is dropped here, named."""
    own = own_names(params, st)
    fams = {n.split("_", 1)[0] for n in own if "_" in n}
    return name in own or name in fams or name.startswith(ROUND_PREFIX)


def flat_schema(t):
    """A provider schema as the collector's menu row takes it: `{name, description, parameters}`. The OpenAI
    form `{type: function, function: {...}}` is unwrapped."""
    t = _obj(t)
    if isinstance(t.get("function"), dict):
        t = t["function"]
    if not isinstance(t.get("name"), str) or not t["name"]:
        return None
    out = {"name": t["name"], "description": _text(t.get("description") or ""),
           "parameters": t.get("parameters") if isinstance(t.get("parameters"), dict) else
           {"type": "object", "properties": {}}}
    return out


def turns_of(messages):
    """The caller's messages as turns: meclaw turns pass, `{role, content}` becomes a text turn."""
    out = []
    for m in messages or []:
        m = _obj(m)
        if m.get("type"):
            out.append(m)
        elif m.get("role") in ("user", "assistant") and m.get("content") is not None:
            out.append({"origin": m["role"], "type": "text", "text": _text(m["content"])})
    return out


# ─────────────────────────────────────────────── the child's first message

def frame_pack():
    # `instructions.frame`, not `identity.*`: affinity's identity pack is ONE rendered leaf `system.identity`
    # and replaces the whole family (measured: the frame was gone after the first pack).
    return {"header": {"route": "in_pack"}, "system": {"instructions": {"frame": {"text": FRAME}}},
            "messages": []}


def episode(params, turn_id, text, happened_at=""):
    # The universal audience (OR-SA-32): memory-hive shows a row to a round whose audience is a subset of the
    # row's; a start memory filed under the agent alone would come back in no caller's turn.
    head = {"route": "in_episode", "session_id": SEED_SESSION, "turn_id": turn_id, "channel": "seed",
            "audience_set": json.dumps(["*"])}
    if happened_at:
        head["happened_at"] = happened_at
    return {"header": head, "messages": [{"origin": "user", "type": "text", "text": text}]}


def start_memories(params):
    """The start memories, once, as episodes: `{what, with?, at?}` -- `at` an ISO instant the memory is
    filed under, without it it is filed as of now."""
    out = []
    for i, m in enumerate(params.get("start_memories") or []):
        m = _obj(m) if isinstance(m, dict) else {"what": m}
        text = _text(m.get("what", ""))
        if not text:
            continue
        if m.get("with"):
            text += " (with %s)" % _text(m["with"])
        out.append(episode(params, "start-%d" % i, "A memory of yours: " + text, str(m.get("at") or "")))
    return out


def boot(st, params):
    """Once per child life, after the state is read back: the frame, the affinity tool's menu row and the menu
    tick; the start memories once per agent (the `seeded` mark lives in `./door_store`, so a respawned child does
    not write them again). No identity boot and no gate: the identity is the colony's, it arrives by pack, and a
    turn never waits for it."""
    # The menu tick: the collector asks its answerers (tools, curator, memory) for their tools; the substrate
    # hands no message at spawn, so the first message of the door is the occasion.
    out = [frame_pack(), {"header": {"route": "in_menu", "tool_answerer": "affinity"},
                          "schemas": [AFFINITY_TOOL], "messages": []},
           {"header": {"route": "mutation_committed"}, "messages": []}]
    if not st.get("seeded"):
        out += start_memories(params)
        st["seeded"] = True
    st["boot"] = "done"
    return out


# ─────────────────────────────────────────────── the rim lanes

def _int(v, default):
    try:
        return int(v)
    except (TypeError, ValueError):
        return default


def _names(v):
    """A list of tool names from a hop value: a JSON array (hop values travel as strings) or a list."""
    if isinstance(v, str):
        try:
            v = json.loads(v)
        except ValueError:
            v = [v] if v else []
    return [str(n) for n in v if isinstance(n, str) and n] if isinstance(v, list) else []


def strong_on(params):
    """The second brain is on when `params.strong` names its model (or registry subscription); empty = off."""
    return bool(str(params.get("strong") or "").strip())


def stage_of(params, hop):
    asked = str(hop.get("stage") or "fast")
    return "strong" if asked == "strong" and strong_on(params) else "fast"


def back(t, extra=None):
    """The hop of a rim message that answers turn `t`: its id and the caller the rim edge stamped."""
    head = {"turn_id": str(t.get("turn_id") or "")}
    if t.get("caller"):
        head["caller"] = str(t["caller"])
    head.update(extra or {})
    return head


def seen(st, tid):
    return (tid in (st.get("answered") or {}) or tid == st.get("active")
            or any(e.get("turn_id") == tid for e in st.get("queue") or []))


def on_turn(st, params, hop, body):
    keys = round_keys(hop)
    tid = keys.get("turn_id")
    caller = str(hop.get("caller") or "")
    if not tid:
        return [rim("error", {"error_code": "turn_without_id"}, {"caller": caller} if caller else None)]
    if seen(st, tid):
        # A turn id is answered once (rest C7): a repeat -- a caller's retry, a replay after a restart -- is
        # refused, named, and never runs a second round.
        return [rim("error", {"error_code": "turn_seen", "turn_id": tid}, back({"turn_id": tid, "caller": caller}))]
    st["seq"] = int(st.get("seq") or 0) + 1
    st.setdefault("queue", []).append({
        "turn_id": tid, "priority": max(0, _int(hop.get("priority"), DEFAULT_PRIORITY)), "seq": st["seq"],
        "deadline_ms": max(0, _int(hop.get("deadline_ms"), 0)), "hop": dict(hop), "body": body})
    return start_next(st, params)


def _waiting(params, e):
    hop = _obj(e.get("hop"))
    return {"turn_id": e["turn_id"], "caller": str(hop.get("caller") or ""), "stage": stage_of(params, hop)}


def _expire(st, params, e):
    t = _waiting(params, e)
    mark_answered(st, params, e["turn_id"])
    return rim("answer", dict(answer_slot(t, ""), expired=True), back(t))


def _past(e, moment):
    return bool(e.get("deadline_ms")) and moment > int(e["deadline_ms"])


def start_next(st, params, moment=0):
    """While no turn runs: the queued turn of the highest priority, then the earliest; one past its deadline ends
    expired without a model call and the next is taken. A queued turn past its deadline behind a running one ends
    the same way, and the deadline watchdog is armed for the earliest deadline still waiting. `moment` is the
    watchdog's own time when it fired (the door's clock may stand still in a test, `now_utc`)."""
    moment = max(now_ms(params), int(moment or 0))
    out = []
    while not st.get("active") and st.get("queue"):
        q = st["queue"]
        q.sort(key=lambda e: (e.get("priority", DEFAULT_PRIORITY), e.get("seq", 0)))
        e = q.pop(0)
        if _past(e, moment):
            out.append(_expire(st, params, e))
            continue
        out += begin(st, params, e, _waiting(params, e))
    # Review I2 (OR-AG-50): the deadline was checked only when a turn could begin, so behind a turn that hangs a
    # queued caller heard nothing. Now it ends at its deadline wherever it stands in the queue.
    q = st.get("queue") or []
    for e in [e for e in q if _past(e, moment)]:
        q.remove(e)
        out.append(_expire(st, params, e))
    return out + arm_deadline(st, params, moment)


def arm_deadline(st, params, moment):
    """One one-shot watchdog for the earliest deadline of the queue (R-AG-1: once, retriggerable, no tick): armed
    one millisecond after it, re-armed only when an earlier one comes; a strike that finds nothing due re-arms for
    the next. A deadline already past never arms (`at_in_past`) -- `start_next` ended it."""
    due = [int(e["deadline_ms"]) for e in st.get("queue") or [] if e.get("deadline_ms")]
    if not due:
        return []
    at = min(due) + 1
    armed = int(st.get("deadline_at") or 0)
    if at <= moment or (moment < armed <= at):
        return []
    st["deadline_at"] = at
    order = once("deadline", at, "../door", {"messages": [], "deadline": {"at": at}})
    order["emit_headers"] = {"route": "turn_deadline"}
    order["header"] = {"route": "watch_op"}
    order["messages"] = []
    return [order]


def on_deadline(st, params, body):
    """The deadline watchdog struck: every queued turn past its deadline ends expired, the next deadline arms."""
    at = _int(_obj(body.get("deadline")).get("at"), 0)
    st["deadline_at"] = 0
    return start_next(st, params, at)


def menu_of(params, tools, st):
    """The client tools of a turn (OR-SA-2): a name the agent owns is dropped -- the menu merge orders rows by
    answerer and `client` sorts first, so the caller's tool would otherwise win against the own one."""
    schemas, dropped, names = [], [], set()
    for t in tools or []:
        s = flat_schema(t)
        if s is None or s["name"] in names:
            continue
        names.add(s["name"])
        if is_own(params, s["name"], st):
            dropped.append(s["name"])
        else:
            schemas.append(s)
    return schemas, dropped


def begin(st, params, e, t):
    """The queued turn begins: its round opens at the collector."""
    hop, body = _obj(e.get("hop")), _obj(e.get("body"))
    keys = round_keys(hop)
    keys.setdefault("session_id", "default")
    keys.setdefault("channel", "turn")
    keys.setdefault("audience_set", json.dumps(["*"]))
    keys.pop("iter", None)
    st.setdefault("sessions", {})[keys["session_id"]] = {"channel": keys["channel"],
                                                         "audience_set": keys["audience_set"]}
    schemas, dropped = menu_of(params, body.get("tools"), st)
    t.update(keys=keys, schemas=schemas, required=_names(hop.get("required_tools")), called=[],
             followed=False, iters=0, usage={"in": 0, "cached_in": 0, "cache_write": 0, "out": 0}, cost=0.0)
    st["active"] = t["turn_id"]
    st.setdefault("turns", {})[t["turn_id"]] = t
    head = dict(keys, route="in_turn", agent_id=agent_id(params), sa_stage=t["stage"])
    # Who this turn is with (GH #834): the subject of the brief the collector asks the colony's affinity.
    if hop.get("counterpart"):
        head["counterpart"] = str(hop["counterpart"])
    if dropped:
        head["client_tools_dropped"] = json.dumps(dropped)
    scope(params, head)
    # A turn may require a tool call of its FIRST brain call (`tool_scope.require`, the normal form every agent
    # has: `tool_choice` required/any). The collector requires it of that one call; the loop's next calls go
    # without, so the turn can still end in text. Absent = the turn of before, no key on the hop.
    ts = body.get("tool_scope")
    if isinstance(ts, dict) and ts.get("require") is True:
        head["tool_require"] = "1"
    # Menu BEFORE the turn, in ONE output, at the same collector: its store writes the menu row before the
    # round opens, so the brain call of this turn already carries the client tools.
    menu = {"header": {"route": "in_menu", "tool_answerer": "client"}, "schemas": schemas, "messages": []}
    return [menu, {"header": head, "messages": turns_of(body.get("messages"))}]


def scope(params, head):
    allow = [str(n) for n in (params.get("tools_allow") or []) if isinstance(n, str)]
    deny = [str(n) for n in (params.get("tools_deny") or []) if isinstance(n, str)]
    if allow or deny:
        head["sa_scope"] = "1"
        head["tools_allow"] = json.dumps(allow)
        head["tools_deny"] = json.dumps(deny)


def follow_up(st, params, t, missing):
    """The one follow-up of a turn whose answer lacks a required tool (plan A2): the code checks, not
    `tool_scope.require` -- that has no effect on a native Sonnet/Opus 5.5 (`translate_anthropic.rs`). It runs
    in the same session under its own round id, so the collector opens a fresh round and the window holds the
    turn it follows."""
    t["followed"] = True
    # `.`, not `~`: the collector keys events on `~` and maps it to `_` in a foreign id
    # (collector/assemble `disarm`), so a `~follow` round came back as `_follow` and lost its turn.
    t["follow_id"] = "%s.follow" % t["turn_id"]
    head = dict(t["keys"], route="in_turn", turn_id=t["follow_id"], agent_id=agent_id(params), sa_stage=t["stage"])
    scope(params, head)
    menu = {"header": {"route": "in_menu", "tool_answerer": "client"}, "schemas": t.get("schemas") or [],
            "messages": []}
    text = "Call %s now." % ", ".join(missing)
    return [menu, {"header": head, "messages": [{"origin": "user", "type": "text", "text": text}]}]


def owner_of(st, tid):
    """The turn a round id belongs to: itself, or the turn whose follow-up it is."""
    turns = st.get("turns") or {}
    if tid in turns:
        return tid
    return next((k for k, t in turns.items() if t.get("follow_id") == tid), tid)


def mark_answered(st, params, tid):
    now = now_ms(params)
    keep = {k: v for k, v in (st.get("answered") or {}).items() if now - int(v) < SEEN_KEEP_MS}
    keep[str(tid)] = now
    st["answered"] = keep


def answer_slot(t, text):
    return {"turn_id": t.get("turn_id"), "text": text, "iters": int(t.get("iters") or 0),
            "usage": dict(t.get("usage") or {"in": 0, "cached_in": 0, "cache_write": 0, "out": 0}),
            "cost": float(t.get("cost") or 0.0), "stage": t.get("stage") or "fast"}


def drop_round(st, rid):
    """The open client calls of round `rid` go: a later timeout of one of them finds nothing and sends no
    `in_tool` into a closed round (review M2)."""
    for cid in (st.get("pending") or {}).pop(rid, []) or []:
        (st.get("calls") or {}).pop(cid, None)


def finish(st, params, tid):
    """The open turn ends: its id is answered, its calls -- and those of its follow-up round -- are dropped, the
    next queued turn may begin."""
    mark_answered(st, params, tid)
    t = (st.get("turns") or {}).pop(tid, None) or {"turn_id": tid}
    if st.get("active") == tid:
        st["active"] = None
    drop_round(st, tid)
    if t.get("follow_id"):
        drop_round(st, t["follow_id"])
    return t


def on_usage(st, params, ctx, hop, body):
    """One brain (or strong) answer of the open turn: its tokens, its cost and the tools it called, summed for the
    turn's `answer` -- the same hop fields the curator's tap reads."""
    t = (st.get("turns") or {}).get(owner_of(st, str(ctx.get("turn_id") or "")))
    if t is None:
        return []
    t["iters"] = int(t.get("iters") or 0) + 1
    u = t.setdefault("usage", {"in": 0, "cached_in": 0, "cache_write": 0, "out": 0})
    for slot, field in (("in", "tokens_prompt"), ("cached_in", "tokens_cached"),
                        ("cache_write", "tokens_cache_write"), ("out", "tokens_completion")):
        u[slot] = int(u.get(slot) or 0) + _int(hop.get(field), 0)
    try:
        t["cost"] = float(t.get("cost") or 0.0) + float(hop.get("cost") or 0.0)
    except (TypeError, ValueError):
        pass
    called = t.setdefault("called", [])
    for c in calls_of(body.get("messages") or []):
        if c.get("name") and c["name"] not in called:
            called.append(c["name"])
    for m in body.get("messages") or []:
        n = _obj(m).get("name")
        if _obj(m).get("type") == "tool_call" and isinstance(n, str) and n and n not in called:
            called.append(n)
    return []


def on_tool_result(st, params, hop, body):
    r = _obj(body.get("tool_result"))
    keys = round_keys(hop)
    missing = [k for k in ("turn_id", "session_id", "iter") if not keys.get(k)]
    if missing or not r.get("id"):
        # Without its round the collector cannot file the result (`in_tool` reads turn, session and iteration
        # from the context): refused here, named, instead of parked in a round nobody opens.
        return [rim("error", {"error_code": "tool_result_unkeyed", "id": r.get("id"),
                              "missing": missing + ([] if r.get("id") else ["id"])},
                    {"turn_id": keys.get("turn_id", "")})]
    if str(r["id"]) in (st.get("timed_out") or []):
        # Its timeout already answered this call in the round; a second result would answer it twice.
        sys.stderr.write("simple-agent door: a client result after its timeout: %s\n" % r["id"])
        return []
    pend = st.setdefault("pending", {})
    left = [i for i in pend.get(keys["turn_id"], []) if i != str(r["id"])]
    pend[keys["turn_id"]] = left
    (st.get("calls") or {}).pop(str(r["id"]), None)
    text = _text(r.get("content", ""))
    if r.get("is_error"):
        text = "error: " + text
    return [in_tool(st, keys, str(r["id"]), str(hop.get("tool_name") or ""), text)]


def in_tool(st, keys, cid, name, text):
    """One tool result into its round; `sa_stage` rides along, so the round's next brain call takes the turn's
    stage (the edge lifts it into the context)."""
    t = (st.get("turns") or {}).get(owner_of(st, keys.get("turn_id", ""))) or {}
    head = dict(keys, route="in_tool", sa_stage=t.get("stage") or "fast")
    if name:
        head["tool_name"] = name
    return {"header": head, "messages": [{"origin": "tool", "type": "tool_result", "id": cid, "text": text}]}


def on_client_timeout(st, params, body):
    """A client call unanswered after `client_tool_timeout_ms`: its result is a named timeout and the round goes
    on (plan A2)."""
    cid = str(_obj(body.get("ctool")).get("id") or "")
    call = (st.get("calls") or {}).pop(cid, None)
    if call is None:
        return []
    keys = {k: v for k, v in call.items() if k in ("turn_id", "session_id", "iter", "channel", "audience_set")}
    pend = st.setdefault("pending", {})
    pend[keys.get("turn_id", "")] = [i for i in pend.get(keys.get("turn_id", ""), []) if i != cid]
    st["timed_out"] = ((st.get("timed_out") or []) + [cid])[-256:]
    ms = int(params.get("client_tool_timeout_ms") or 30000)
    return [in_tool(st, keys, cid, str(call.get("name") or ""),
                    "error: timeout: the caller did not answer %s within %d ms" % (call.get("name") or cid, ms))]


def on_close(st, params, body):
    c = _obj(body.get("close"))
    sid = str(c.get("session_id") or "")
    if not sid:
        return [rim("error", {"error_code": "close_without_session"})]
    known = _obj(st.get("sessions", {}).get(sid))
    return [{"header": {"route": "in_close", "session_id": sid, "channel": known.get("channel") or "turn",
                        "audience_set": known.get("audience_set") or json.dumps(["*"]), "sa_kind": "close"},
             "messages": []}]


def on_close_report(hop, ctx):
    if hop.get("phase") != "close" or ctx.get("sa_kind") != "close":
        return []
    # The dream after the close pass: the memory hive's own trigger of its nightly run.
    dream = {"header": {"route": "clock_op"}, "op": "trigger", "schedule_name": "nightly-dream", "messages": []}
    return [dream, rim("close_report", {"session_id": ctx.get("session_id"), "ok": True,
                                        "added": hop.get("added"), "closed": hop.get("closed")})]


# ─────────────────────────────────────────────── the round's own lanes

def calls_of(turns):
    out = []
    for i, t in enumerate(t for t in turns if t.get("type") == "tool_call"):
        try:
            fn = json.loads(t.get("text") or "")
        except ValueError:
            fn = {}
        fn = _obj(fn)
        # The dispatcher's tool turn carries the call's ARGUMENTS as its text; an assistant turn of the
        # provider form carries `{name, arguments}`.
        args = fn.get("arguments") if "name" in fn and "arguments" in fn else fn
        if isinstance(args, str):
            try:
                args = json.loads(args)
            except ValueError:
                pass
        out.append({"id": str(t.get("id") or "call-%d" % i), "name": fn.get("name"), "args": args})
    return out


def on_tool(st, params, hop, ctx, body):
    """A call the round's own cells do not serve: the agent's affinity tool, which leaves on the rim as
    `affinity_propose`, or a client tool, which leaves on the rim as `calls` -- both with their round on the
    hop (V-T)."""
    name = str(hop.get("tool_name") or "")
    cid = str(hop.get("tool_call_id") or "")
    call = (calls_of(body.get("messages") or []) or [{"id": cid, "name": name, "args": {}}])[0]
    keys = round_keys(ctx)
    if name == AFFINITY_TOOL["name"]:
        args = _obj(call.get("args"))
        if args.get("op") not in AFFINITY_OPS:
            return [{"header": dict(keys, route="in_tool", tool_name=name,
                                    sa_stage=_obj((st.get("turns") or {}).get(owner_of(st, keys.get("turn_id", ""))))
                                    .get("stage") or "fast"),
                     "messages": [{"origin": "tool", "type": "tool_result", "id": cid,
                                   "text": "error: op must be one of %s" % ", ".join(AFFINITY_OPS)}]}]
        # The proposal leaves for the agent's entry in the colony's affinity; the actor is the embedder's edge
        # (`'agent:' + hop.agent_id`), never the body's. The call id waits here for an answer that names none.
        props = st.setdefault("proposing", [])
        props.append([keys.get("turn_id", ""), cid])
        del props[:-64]
        hop_out = dict(keys, agent_id=agent_id(params), tool_name=name, tool_call_id=cid)
        out = rim("affinity_propose", args, hop_out)
        out["messages"] = [{"origin": "assistant", "type": "tool_call", "id": cid, "text": json.dumps(args)}]
        return [out]
    out = []
    rkey = "%s/%s" % (keys.get("turn_id", ""), keys.get("iter", ""))
    watched = st.setdefault("watched", [])
    if rkey not in watched:
        # The round's watchdog (OR-SA-15): the collector sweeps a stuck round only when asked. One one-shot
        # schedule per round, after the idle window, retriggerable by name -- no tick.
        st["watched"] = (watched + [rkey])[-64:]
        idle = int(params.get("round_idle_ms") or 120000)
        order = once("round-%s" % rkey, now_ms(params) + idle + 1000, "../collector",
                     {"messages": []})
        order["emit_headers"] = {"route": "in_round_sweep"}
        order["header"] = {"route": "watch_op"}
        order["messages"] = []
        out.append(order)
    pend = st.setdefault("pending", {})
    pend[keys.get("turn_id", "")] = sorted(set(pend.get(keys.get("turn_id", ""), [])) | {cid})
    while len(pend) > 64:
        pend.pop(next(iter(pend)))
    st.setdefault("calls", {})[cid] = dict(keys, name=name)
    # The client's deadline (plan A2): one one-shot watchdog per call, no tick; an answered call finds nothing.
    order = once("ctool-%s" % cid, now_ms(params) + int(params.get("client_tool_timeout_ms") or 30000),
                 "../door", {"messages": [], "ctool": {"id": cid}})
    order["emit_headers"] = {"route": "client_timeout"}
    order["header"] = {"route": "watch_op"}
    order["messages"] = []
    out.append(order)
    owner = (st.get("turns") or {}).get(owner_of(st, keys.get("turn_id", ""))) or {}
    hop_out = dict(keys, tool_name=name, tool_call_id=cid)
    if owner.get("caller"):
        hop_out["caller"] = owner["caller"]
    out.append(rim("calls", {"id": cid, "name": name, "arguments": call.get("args")}, hop_out))
    return out


def on_propose_ack(st, params, hop, ctx, body):
    """The colony affinity's answer to one `affinity_propose`, back into its round as the tool's result. Anything
    but an accepted write -- a rejected op, affinity's `error` (the embedder stamps `propose_outcome`) -- is a
    result that says `error:`, never silence."""
    keys = round_keys(ctx)
    props = st.setdefault("proposing", [])
    res = [dict(m) for m in body.get("messages") or [] if _obj(m).get("type") == "tool_result"]
    ids = {str(m.get("id") or "") for m in res}
    pending = [p for p in props if p[0] == keys.get("turn_id", "")]
    cid = next((p[1] for p in pending if p[1] in ids), None) or (pending[0][1] if pending else "")
    if [keys.get("turn_id", ""), cid] in props:
        props.remove([keys.get("turn_id", ""), cid])
    if not keys.get("turn_id"):
        sys.stderr.write("simple-agent door: an affinity answer outside a round: %s\n" % json.dumps(hop))
        return []
    failed = str(hop.get("propose_outcome") or "") == "error" or str(hop.get("outcome") or "") != "accepted"
    if not res:
        res = [{"origin": "tool", "type": "tool_result", "id": cid,
                "text": "affinity answered %s" % (hop.get("reason_code") or hop.get("error_code") or "nothing")}]
    for m in res:
        m["id"] = str(m.get("id") or cid)
        text = _text(m.get("text") or "")
        if failed and not text.startswith("error:"):
            m["text"] = "error: " + text
    t = (st.get("turns") or {}).get(owner_of(st, keys.get("turn_id", ""))) or {}
    return [{"header": dict(keys, route="in_tool", tool_name=AFFINITY_TOOL["name"], sa_stage=t.get("stage") or "fast"),
             "messages": res}]


def on_answer(st, params, hop, ctx, body):
    text = "\n".join(t.get("text") or "" for t in body.get("messages") or [] if t.get("type") == "text").strip()
    rid = str(ctx.get("turn_id") or "")
    tid = owner_of(st, rid)
    if tid in (st.get("answered") or {}):
        return []
    t = (st.get("turns") or {}).get(tid) or {"turn_id": tid}
    missing = [n for n in t.get("required") or [] if n not in (t.get("called") or [])]
    if missing and not t.get("followed"):
        drop_round(st, rid)
        return follow_up(st, params, t, missing)
    stale = str(hop.get("round_stale") or "") == "1" or bool((st.get("pending") or {}).get(rid))
    finish(st, params, tid)
    slot = answer_slot(t, text)
    if str(hop.get("partial") or "") == "1" or str(hop.get("round_capped") or "") == "1":
        slot["partial"] = True
    # A client call still without its result: the round's watchdog swept it as lost, and the turn went on.
    if stale:
        slot["stale"] = True
    if missing:
        slot["missing_required"] = missing
    return [rim("answer", slot, back(t))] + start_next(st, params)


def on_round_error(st, params, hop, ctx):
    tid = owner_of(st, str(ctx.get("turn_id") or ""))
    if tid in (st.get("answered") or {}):
        return []
    t = finish(st, params, tid)
    return [rim("error", {"error_code": hop.get("error_code") or "model_error", "turn_id": tid}, back(t))] + \
        start_next(st, params)


def on_pack_ack(st, hop, ctx):
    # The receipt of the door's own frame pack; a refused frame is named on the rim.
    if hop.get("error_code"):
        return [rim("error", {"error_code": hop.get("error_code"), "kind": "pack"})]
    return []


def on_tools_enabled(st, body):
    """The agent's enabled tool families (A4's `./tool_gate`): kept durable, read at every turn's menu."""
    names = body.get("tools_enabled")
    st["enabled"] = sorted({str(n) for n in names if isinstance(n, str)}) if isinstance(names, list) else []
    return []


def store_op(kind, args):
    return {"header": {"route": "door_store", "ds_kind": kind},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": "ds-" + kind, "text": json.dumps(args)}]}


def snapshot(st):
    return {k: st.get(k) for k in DURABLE}


def hydrate(st, body):
    """The state the last child life left in `./door_store`; nothing there (a new agent, a refused read) is an
    empty door."""
    rows = []
    try:
        rows = json.loads((body.get("messages") or [{}])[0].get("text") or "[]")
    except (ValueError, AttributeError, IndexError):
        rows = []
    for r in rows if isinstance(rows, list) else []:
        snap = _obj(r).get("payload")
        if isinstance(snap, str):
            try:
                snap = json.loads(snap)
            except ValueError:
                snap = {}
        for k, v in _obj(snap).items():
            if k in DURABLE and v is not None:
                st[k] = v
    st["_written"] = json.dumps(snapshot(st), sort_keys=True)


def persist(st):
    now = json.dumps(snapshot(st), sort_keys=True)
    if now == st.get("_written"):
        return []
    st["_written"] = now
    return [store_op("write", {"operation": "insert", "table": STATE_TABLE,
                               "row": {"slot": STATE_SLOT, "payload": snapshot(st)},
                               "replace": {"slot": STATE_SLOT}})]


def dispatch(doc, st):
    header = _obj(_obj(doc.get("envelope")).get("header"))
    hop, ctx, body = _obj(header.get("hop")), _obj(header.get("context")), _obj(doc.get("body"))
    params = _obj(doc.get("params"))
    route = hop.get("route")
    handlers = {
        "turn": lambda: on_turn(st, params, hop, body),
        "tool_result": lambda: on_tool_result(st, params, hop, body),
        "close": lambda: on_close(st, params, body),
        "tool": lambda: on_tool(st, params, hop, ctx, body),
        "in_propose_ack": lambda: on_propose_ack(st, params, hop, ctx, body),
        "answer": lambda: on_answer(st, params, hop, ctx, body),
        "round_error": lambda: on_round_error(st, params, hop, ctx),
        "usage": lambda: on_usage(st, params, ctx, hop, body),
        "client_timeout": lambda: on_client_timeout(st, params, body),
        "turn_deadline": lambda: on_deadline(st, params, body),
        "close_report": lambda: on_close_report(hop, ctx),
        "tools_enabled": lambda: on_tools_enabled(st, body),
        "pack_ack": lambda: on_pack_ack(st, hop, ctx),
    }
    if route in handlers:
        return handlers[route]()
    if route == "reject" and ctx.get("sa_kind") == "close":
        return [rim("close_report", {"session_id": ctx.get("session_id"), "ok": False, "added": 0, "closed": 0})]
    if hop.get("msg_type") == "timer_op_error":
        sys.stderr.write("simple-agent door: watchdog refused: %s\n" % json.dumps(body.get("meta")))
        return []
    # Everything else that reaches this cell is drained on purpose: sidecar sections nobody else reads,
    # acknowledgements, a memory answer outside a round.
    return []


def on_message(doc, st):
    header = _obj(_obj(doc.get("envelope")).get("header"))
    hop, ctx, body = _obj(header.get("hop")), _obj(header.get("context")), _obj(doc.get("body"))
    if hop.get("route") == "door_store_ack":
        if hop.get("error_code"):
            sys.stderr.write("simple-agent door: door_store answered %s\n" % hop.get("error_code"))
        if ctx.get("ds_kind") != "read" or st.get("hydrated"):
            return []
        hydrate(st, body)
        st["hydrated"] = True
        held = st.pop("held", [])
        out = boot(st, _obj((held[0] if held else doc).get("params")))
        for d in held:
            out += dispatch(d, st)
        return out + persist(st)
    if hop.get("route") == "door_store_retry":
        # The read's watchdog: an answer already came, or the read is asked again (review M4).
        return [] if st.get("hydrated") else ask_store(_obj(doc.get("params")))
    if not st.get("hydrated"):
        # A new child life reads the door's state back before it serves anything; what arrives meanwhile waits
        # here in arrival order (one read per child life, asked again after `store_read_ms` without an answer).
        st.setdefault("held", []).append(doc)
        if st.get("asking"):
            return []
        st["asking"] = True
        return ask_store(_obj(doc.get("params")))
    return dispatch(doc, st) + persist(st)


def ask_store(params):
    """The read of the door's state, and its one-shot watchdog: a read the store never answers (it restarted
    mid-read) is asked again after `store_read_ms`, so the held messages never wait for a lost answer."""
    wait = max(1, _int(params.get("store_read_ms"), 10000))
    order = once("ds-read", now_ms(params) + wait, "../door", {"messages": []})
    order["emit_headers"] = {"route": "door_store_retry"}
    order["header"] = {"route": "watch_op"}
    order["messages"] = []
    return [store_op("read", {"operation": "select", "table": STATE_TABLE, "columns": ["payload"],
                              "where": {"slot": STATE_SLOT}}), order]


if __name__ == "__main__":
    if "STATE" not in globals():
        STATE = {}
    sys.stdout.write(json.dumps(on_message(json.load(sys.stdin), STATE)))
